from pathlib import Path
import json,shutil,html,sys
root=Path(__file__).resolve().parents[1]
dest=root/"design/phase17"
out=Path(sys.argv[1]) if len(sys.argv)>1 else root/"output/rouse-reference-board"
refs=root/"evidence/phase17/references"
for p in [dest,out,dest/"images",dest/"brand"]:p.mkdir(exist_ok=True,parents=True)
for p in refs.glob("*.png"):shutil.copyfile(p,dest/"images"/p.name)
shutil.copyfile(root/"evidence/phase16/baseline-landing.png",dest/"images/previous-landing.png")
brand=root/"web/public/brand/rouse"
for name in ["wordmark-dark.svg","wordmark-light.svg","favicon.svg"]:shutil.copyfile(brand/name,dest/"brand"/name)
shutil.copytree(brand/"fonts",dest/"brand/fonts",dirs_exist_ok=True)
data=json.loads((root/"design/phase16/case-data.json").read_text())
E=html.escape
manifest={
 "phase":17,"checkedAt":"2026-11-08","direction":"Working Precedent",
 "scope":"Reference research and translation specimens; no product integration",
 "references":[
  {"id":"identity","classification":"target","source":"web/public/brand/rouse","borrow":"Canonical wordmark, type roles, functional color and retained-counter geometry","avoid":"Replacing the identity with a reference site's colors/fonts"},
  {"id":"composition","classification":"target","source":"design/phase16","borrow":"Paired current evidence and prior reviewed judgment; ordered mobile flow","avoid":"Shipping study controls or snapshot data as live behavior"},
  {"id":"github","classification":"functional example","url":data["evidenceUrl"],"capture":"images/github-record-context.png","borrow":"Keep immutable artifact identity and human context adjacent to the record","avoid":"Repository chrome, contribution graphs, arbitrary code-diff density"},
  {"id":"sentry","classification":"functional example","url":"https://docs.sentry.io/product/issues/issue-details/","imageSource":"https://docs.sentry.io/mdx-images/issue-details-breakdown-MAZU5VNB.png","capture":"images/sentry-event-header.png","borrow":"Recognizable error identity anchored to its execution context","avoid":"Resolve/archive workflow, trend charts, assignment and broad monitoring"},
  {"id":"details","classification":"functional example","url":"https://design-system.service.gov.uk/components/details/","example":"https://design-system.service.gov.uk/components/details/default/","capture":"images/govuk-details-closed.png","borrow":"Native disclosure for secondary depth, retaining essential decisions outside","avoid":"Hiding procedure, match reasons, reviewer or exact blob"},
  {"id":"validation","classification":"functional example","url":"https://design-system.service.gov.uk/components/error-summary/","example":"https://design-system.service.gov.uk/components/error-summary/default/","capture":"images/govuk-error-summary.png","borrow":"A concise correction summary linked to the invalid field, with consistent inline wording","avoid":"Treating onchain failure or a gateway outage as a mistake in reviewer input"},
  {"id":"previous-landing","classification":"anti-reference","source":"evidence/phase16/baseline-landing.png","capture":"images/previous-landing.png","borrow":"Preserve the real read/recall integration and separate workspace entry","avoid":"Tilted cards, stale awaiting-confirmation example and oversized repeated slogans"}
 ],
 "deferred":[
  {"source":"https://linear.app/","reason":"Phase16 body capture incomplete; header alone adds no unique pattern beyond selected references. Not accepted as a whole-page target."},
  {"source":"https://docs.stripe.com/workbench/overview","reason":"Public documentation checked, but log tools/command surfaces add no unique needed pattern here. Not selected."}
 ]
}
(dest/"references.json").write_text(json.dumps(manifest,indent=2)+"\n")
css="""
@font-face{font-family:Head;src:url('brand/fonts/SpaceGrotesk.ttf');font-weight:300 700;font-display:swap}
@font-face{font-family:Body;src:url('brand/fonts/DMSans.ttf');font-weight:100 1000;font-display:swap}
@font-face{font-family:Mono;src:url('brand/fonts/DMMono.ttf');font-weight:400;font-display:swap}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#e9e9e1;color:#17201c;font:16px/1.65 Body,Arial,sans-serif}a{color:inherit;text-decoration-thickness:1px;text-underline-offset:4px}a,button,input,summary{outline-offset:5px}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #5c7f42}main{max-width:1424px;padding:45px 56px;margin:auto}header{display:flex;justify-content:space-between;gap:25px;align-items:center;border-bottom:2px solid;padding-bottom:30px}.wordmark{width:210px;height:auto;display:block}.label{font:11px/1.7 Mono,monospace;letter-spacing:.05em;color:#57624f}.intro{padding:42px 0 30px}.intro h1{font:600 48px/1.08 Head,sans-serif;letter-spacing:-.055em;max-width:850px;margin:15px 0 24px}.intro p{font-size:17px;max-width:890px;color:#485448}.locked{display:flex;flex-wrap:wrap;gap:15px 30px;border-top:1px solid #a0a696;border-bottom:1px solid #a0a696;padding:19px 0;font-size:12px}.locked b{margin-right:7px}.jump{display:flex;gap:22px;flex-wrap:wrap;font-size:12px;padding:22px 0 0}.jump a{min-height:38px;display:inline-flex;align-items:center}.reference{border-top:1px solid #9ca490;padding:36px 0 42px;scroll-margin-top:18px}.ref-title{display:flex;justify-content:space-between;gap:40px;align-items:start;margin-bottom:27px}.ref-title h2{font:600 31px/1.15 Head;letter-spacing:-.04em;margin:10px 0 0}.tag{font:10px Mono;padding:7px 12px;border:1px solid #809072;white-space:nowrap;margin-top:7px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:34px;align-items:start}.source,.application{min-width:0}.capture{margin:14px 0 13px;border:1px solid #aab09f;background:#f7f7f1;min-height:166px;display:grid;place-items:center;padding:20px}.capture img{max-width:100%;height:auto;max-height:230px;display:block}.capture.strip{min-height:150px}.capture.rouse{background:#0e1212;border-color:#34403d;padding:17px}.capture.rouse img{max-height:220px}.caption{font-size:12px;line-height:1.65;color:#52604e;margin:10px 0 17px}.caption a{overflow-wrap:anywhere}.decisions{display:grid;grid-template-columns:1fr 1fr;gap:22px}.decisions h3{font:600 15px Head;margin:15px 0 8px}.decisions p{font-size:13px;line-height:1.7;margin:0;color:#485448}.rule{background:#d6e6bc;border-left:3px solid #435c2e;padding:16px 20px;font-size:14px;line-height:1.6;margin-top:21px}.rule b{font-family:Head;font-size:17px;display:block;margin-bottom:5px}.mini{background:#0e1212;color:#f5f5ef;padding:25px 25px 23px;margin-top:14px;min-height:166px;font-size:14px}.mini .eyebrow{font:10px Mono;color:#a1aaa5}.mini h3{font:600 22px/1.2 Head;margin:13px 0;letter-spacing:-.03em}.mini p{font-size:12px;line-height:1.7;color:#bbc7b7;margin:9px 0}.mini code{font:11px/1.8 Mono;overflow-wrap:anywhere;color:#c8ed9b;display:block;margin-top:12px}.mini details{border-top:1px solid #34403d;padding-top:14px;margin-top:15px;font-size:12px}.mini summary{cursor:pointer;min-height:44px;display:list-item;color:#c7d2c3}.mini .critical{border-left:2px solid #c8ed9b;padding-left:13px}.mini .origin{margin-top:14px;color:#a1aaa5;font-size:12px}.validation-summary{border:1px solid #ef8b6e;padding:15px 17px;margin-bottom:18px}.validation-summary strong{font:600 17px Head;display:block}.validation-summary a{color:#ef8b6e;font-size:13px;display:inline-flex;min-height:44px;align-items:center}.mini label{font-size:13px;display:block}.mini input{width:100%;min-height:46px;padding:10px 12px;margin:8px 0;font:14px Body;color:#f5f5ef;border:1px solid #ef8b6e;background:#17201c;border-radius:0}.mini .field-error{color:#ef8b6e;font-size:12px}.wide-target{background:#0e1212;padding:22px;margin:20px 0}.wide-target img{width:100%;height:auto;display:block}.translate{display:grid;grid-template-columns:1fr 1fr;gap:26px}.sequence{display:flex;gap:0;border:1px solid #9ca490;font:12px/1.6 Mono;margin-top:20px}.sequence span{flex:1;padding:16px;border-right:1px solid #9ca490}.sequence span:last-child{border:0}.sequence .green{background:#d6e6bc}.anti{margin-top:20px;border:1px solid #b2ad9c;display:grid;grid-template-columns:1fr 1fr;gap:30px;padding:26px}.anti img{width:100%;height:280px;object-fit:cover;object-position:top}.anti h2{font:600 26px Head;margin:8px 0 18px;letter-spacing:-.04em}.anti p{font-size:14px;color:#485448}.synthesis{padding:40px 0}.synthesis h2{font:600 32px Head;margin:10px 0 25px;letter-spacing:-.04em}.synthesis-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 40px}.synthesis-grid div{padding:17px 0;border-top:1px solid #9ca490;font-size:14px}.synthesis-grid b{font:600 18px Head;display:block;margin-bottom:6px}.outro{border-top:2px solid;padding:28px 0;font:12px/1.8 Mono;color:#52604e}.compact{max-width:900px}.micro{font-size:11px;color:#52604e}footer{display:flex;justify-content:space-between;gap:25px;border-top:1px solid #9ca490;padding:22px 0;font-size:12px}.status{color:#435c2e}.state-result{font:11px Mono;color:#c8ed9b;min-height:20px;margin-top:10px}
@media(max-width:800px){main{padding:28px 22px}.wordmark{width:150px}header{align-items:start;gap:20px}.intro{padding-top:30px}.intro h1{font-size:35px}.intro p{font-size:15px}.pair,.translate,.anti,.synthesis-grid{grid-template-columns:1fr}.ref-title{gap:18px;display:block}.ref-title h2{font-size:28px}.tag{display:inline-block}.decisions{gap:18px}.reference{padding:28px 0 32px}.capture{min-height:130px;padding:16px}.capture img{max-height:220px}.mini{padding:22px 18px}.wide-target{padding:10px}.sequence{display:block}.sequence span{display:block;border-right:0;border-bottom:1px solid #9ca490}.locked{gap:9px}.jump{gap:15px}.jump a{min-height:44px}.anti{padding:18px;gap:20px}.anti img{height:210px}footer{display:block}footer span{display:block;margin:9px 0}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
"""
(dest/"style.css").write_text(css)
def source(capture,alt,url,note,cls=""):
 return '<div class="capture '+cls+'"><img src="images/'+capture+'" alt="'+E(alt)+'"></div><p class="caption"><a href="'+url+'" target="_blank" rel="noopener noreferrer">Official source ↗</a> · checked8 Nov2026<br>'+note+'</p>'
def decisions(keep,avoid,rule,application):
 return '<div class="decisions"><div><h3>Borrow</h3><p>'+keep+'</p></div><div><h3>Avoid</h3><p>'+avoid+'</p></div></div><div class="rule"><b>'+rule+'</b>'+application+'</div>'
def start(id,num,title,kind="Functional example"):
 return '<section class="reference" id="'+id+'"><div class="ref-title"><div><div class="label">'+num+' / '+id.upper()+'</div><h2>'+title+'</h2></div><span class="tag">'+kind+'</span></div>'
doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rouse — Phase17 reference board</title><link rel="icon" href="brand/favicon.svg"><link rel="stylesheet" href="style.css"><body><main><header><img class="wordmark" src="brand/wordmark-dark.svg" width="210" height="46" alt="Rouse"><div class="label">REFERENCE BOARD / PHASE17<br>08 NOV2026 · WORKING PRECEDENT</div></header><section class="intro"><div class="label">Specific decisions, carried into one product</div><h1>Keep the evidence.<br>Keep the reading path clear.</h1><p>Rouse helps Sui engineers preserve reviewed resolutions and recall them for compatible failures. These references contribute narrow interaction and hierarchy patterns. The Rouse identity and the selected composition remain the targets.</p><div class="locked"><span><b>Identity</b> Rouse / retained counter</span><span><b>Composition</b> Working Precedent</span><span><b>Palette</b> Graphite / lime / execution orange</span></div><nav class="jump" aria-label="Reference sections"><a href="#github">Source context</a><a href="#sentry">Error identity</a><a href="#details">Disclosure</a><a href="#validation">Validation</a><a href="#rouse">Rouse synthesis</a></nav></section>'''
doc+=start("github","01","A reviewed record keeps its origin.")
doc+='<div class="pair"><div class="source"><div class="label">Source / GitHub immutable commit</div>'+source("github-record-context.png","GitHub commit title, branch, parent and immutable identity",data["evidenceUrl"],"A public artifact with its identity and change context. This is the case's actual source commit.")+decisions("Keep artifact identity, source link and human context adjacent. Secondary detail can expand beneath that anchor.","Repository navigation, activity graphs and a full diff as the first view of a procedure.","Keep the procedure attached to its source.","Place reviewer, original artifact link and exact blob directly below the reviewed procedure.")+'</div><div class="application"><div class="label">Rouse translation / Phase16 composition target</div><div class="capture rouse"><img src="images/rouse-origin-blob.png" alt="Rouse reviewer and evidence link immediately above the exact recalled blob"></div><p class="caption">Recorded approved case, not a live integration read. The source and stored record remain in one visual group.</p><p class="micro">Preserve full, inspectable identifiers and valid links. Do not reduce provenance to an unexplained checkmark.</p></div></div></section>'
doc+=start("sentry","02","Recognize the failure before reading the trace.")
doc+='<div class="pair"><div class="source"><div class="label">Source / Sentry public issue documentation</div>'+source("sentry-event-header.png","Sentry's issue header keeps error identity near event context","https://docs.sentry.io/product/issues/issue-details/","Header excerpt from the official documentation illustration. Counts belong to the Sentry example, not to Rouse.","strip")+decisions("A concise error identity and its execution context remain visible before long raw detail.","Resolve/archive controls, assignment queues, trend charts or a monitoring-product expansion.","Keep facts beside the error.","Show actual outcome, source, checkpoint and normalized error. Keep the full trace available below.")+'</div><div class="application"><div class="label">Rouse translation / current transaction</div><div class="capture rouse"><img src="images/rouse-error-identity.png" alt="Rouse normalized MoveAbort summary with command context"></div><p class="caption">Orange identifies the recorded failed execution. A transport outage or an unknown outcome receives its own neutral state.</p><p class="micro">Use Tatum evidence and existing normalization. This reference does not add a Sentry integration or change the resolution-memory product.</p></div></div></section>'
doc+=start("details","03","Disclose depth without hiding the decision.")
doc+='<div class="pair"><div class="source"><div class="label">Source / GOV.UK details component</div>'+source("govuk-details-closed.png","Closed native disclosure from the official GOV.UK component example","https://design-system.service.gov.uk/components/details/","The public component was opened and closed in the browser. The guide reserves disclosure for information needed by fewer readers.")+decisions("Native disclosure, stable labels and retained keyboard focus for secondary information.","Hiding the procedure, matching reasons, reviewer or exact blob behind tabs, hover or an accordion.","Hide depth, keep the decision visible.","Extended package/hash/trace details can expand. The resolution and its essential evidence stay visible.")+'</div><div class="application"><div class="label">Rouse translation / interactive specimen</div><div class="mini" id="disclosure-demo"><div class="critical"><span class="eyebrow">Reviewed procedure · ShalyX</span><h3>Reconcile the exact order before retrying.</h3><p>Confirm the earlier identical cancellation. Otherwise investigate.</p><code class="essential-blob">'+E(data["blob"])+'</code></div><details id="extended-provenance"><summary>Extended provenance</summary><p>Evidence snapshot hash</p><code>'+E(data["evidenceHash"])+'</code><p>Observed Move package</p><code>'+E(data["package"])+'</code></details><div class="state-result" id="disclosure-result">Secondary details closed. Essential record stays visible.</div></div><p class="caption">Interaction specimen using the recorded Rouse case. No API call or new memory write.</p></div></div></section>'
doc+=start("validation","04","Help a reviewer correct the right field.")
doc+='<div class="pair"><div class="source"><div class="label">Source / GOV.UK error summary</div>'+source("govuk-error-summary.png","Official GOV.UK input-error summary with links to fields","https://design-system.service.gov.uk/components/error-summary/","The guide combines a summary with matching inline errors and links to affected inputs. The isolated source example uses placeholder links.")+decisions("A correction summary, consistent inline wording and a focus path to the invalid input.","Using form-validation language for an onchain failure, unknown execution or an unavailable gateway.","Separate input errors from chain outcomes.","Validate required reviewer fields in their own context. Never reinterpret a network failure as a user's mistake.")+'</div><div class="application"><div class="label">Rouse translation / focus-path specimen</div><div class="mini"><div class="validation-summary" role="alert"><strong>Reviewer name required</strong><a href="#board-reviewer" id="reviewer-correction">Enter a reviewer name</a></div><label for="board-reviewer">Named reviewer</label><input id="board-reviewer" autocomplete="off" aria-invalid="true" aria-describedby="reviewer-field-error" placeholder="Engineer name or handle"><div class="field-error" id="reviewer-field-error">Enter a reviewer name</div><div class="state-result" id="focus-result">Use the correction link to focus the field.</div></div><p class="caption">Interaction specimen only. Input is not submitted, stored or used as approval.</p></div></div></section>'
doc+=start("rouse","05","The synthesis belongs to Rouse.","Identity + composition target")
doc+='<div class="label">Exact target / canonical Rouse assets and the selected Phase16 layout</div><div class="wide-target"><img src="images/rouse-paired-evidence.png" alt="Rouse current chain evidence beside a reviewed resolution, reasons and exact blob"></div><div class="translate"><div>'+decisions("Current evidence and earlier judgment occupy comparable space. The exact record and its limits remain visible.","A collage of GitHub chrome, Sentry tools and government styling.","One working canvas, one Rouse identity.","Retain the custom wordmark, self-hosted type, graphite surfaces and restrained state color.")+'</div><div><h3>Mobile reading order</h3><div class="sequence"><span>Intake</span><span>Chain facts</span><span class="green">Reviewed procedure</span><span>Reasons / limits</span><span>Source / blob</span></div><p class="caption">Stack the paired desktop evidence without hiding meaning. Long identifiers wrap; supplemental links and disclosures retain touch targets.</p><p class="caption">Reference images are research material, not assets for the public landing page. Production visuals come from the Rouse interface and approved case.</p></div></div></section>'
doc+='''<section class="anti"><div><div class="label">06 / Anti-reference · earlier public baseline</div><img src="images/previous-landing.png" alt="Earlier Casewake landing with tilted illustrative cards"></div><div><h2>Leave the tilted example behind.</h2><p>Preserve the functioning read/recall journey and separate workspace route. Replace the tilted cards, stale awaiting-confirmation example and repeated oversized slogans.</p><p>The selected page shows a bounded reviewed resolution with its source. It makes the general memory value visible without turning one cancellation incident into the product.</p><p class="caption">Own product baseline captured8 Nov2026. This is an explicit anti-reference, not a template.</p></div></section><section class="synthesis"><div class="label">Implementation handoff</div><h2>Five rules carried forward.</h2><div class="synthesis-grid"><div><b>01 / Bind source to judgment</b>Reviewer, artifact and exact blob form one provenance group below the procedure.</div><div><b>02 / Keep identity close to context</b>Actual chain outcome and normalized error stay near source/checkpoint facts.</div><div><b>03 / Disclose only secondary depth</b>Raw traces and extended hashes may expand; the procedure and essential record remain visible.</div><div><b>04 / Give input errors a focus path</b>Validation summary and inline error agree; correction links focus the field.</div><div><b>05 / Preserve reading order</b>The desktop pair becomes a deliberate mobile sequence; no clipped identifiers or hidden procedure.</div><div><b>No external motion borrowed</b>Native disclosure/focus continuity informs fallback. Phase19 still defines Rouse's request-to-recall motion.</div></div></section><section class="outro"><b class="status">PHASE17 / REFERENCE SYNTHESIS</b><p class="compact">Four external functional references, two internal targets and one explicit anti-reference. Linear's incomplete body render and Stripe Workbench were not selected. This board adds no product integration, new feature or production dependency.</p><p>Next: Phase18 visual asset strategy. Final app implementation, motion QA and production release remain separate.</p></section><footer><span>Rouse / Working Precedent / 08 Nov2026</span><span>Source links and capture provenance: references.json</span></footer></main><script src="board.js"></script></body></html>'''
for a,b in [("PHASE17","PHASE 17"),("Phase17","Phase 17"),("Phase16","Phase 16"),("Phase18","Phase 18"),("Phase19","Phase 19"),("NOV2026","NOV 2026"),("Nov2026","Nov 2026"),("checked8","checked 8"),("captured8","captured 8")]:doc=doc.replace(a,b)
(dest/"index.html").write_text(doc,encoding="utf-8")
(dest/"board.js").write_text("""
const details=document.getElementById('extended-provenance');
details.addEventListener('toggle',()=>{document.getElementById('disclosure-result').textContent=details.open?'Secondary details open. Essential record stays visible.':'Secondary details closed. Essential record stays visible.';});
document.getElementById('reviewer-correction').addEventListener('click',event=>{event.preventDefault();document.getElementById('board-reviewer').focus();document.getElementById('focus-result').textContent='Reviewer field focused. No data was submitted.';});
""")
for p in dest.iterdir():
 if p.is_file():shutil.copyfile(p,out/p.name)
for folder in ["images","brand"]:shutil.copytree(dest/folder,out/folder,dirs_exist_ok=True)
print(json.dumps({"board":str(out/"index.html"),"externalFunctionalReferences":4,"internalTargets":2,"antiReferences":1,"appChanges":False}))
